from datetime import datetime, timedelta
import math


class ParkingMeter:
    FREE_DURATION = timedelta(minutes=15)
    MAX_DURATION = timedelta(hours=24)
    LONG_STAY_FEE = 200.00
    SECONDS_PER_HOUR = 3600

    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        duration = exit - entry

        if duration <= self.FREE_DURATION:
            return 0.0

        if duration > self.MAX_DURATION:
            return self.LONG_STAY_FEE

        hours = math.ceil(duration.total_seconds() / self.SECONDS_PER_HOUR)
        return round(hours * self.hourly_rate, 2)
